{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative, Whole-Person Care</title>
  <meta name="description" content="Practical, evidence-aware holistic medicine focused on lifestyle, labs, and personalized plans. VIP Day option available." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <div class="site-root">
    <header class="topbar">
      <div class="brand">
        <svg class="logo" viewBox="0 0 36 36" aria-hidden="true"><defs><linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#6ee7b7"/><stop offset="1" stop-color="#60a5fa"/></linearGradient></defs><rect rx="6" width="36" height="36" fill="url(#g1)"/><text x="50%" y="58%" font-size="14" fill="#06202a" text-anchor="middle" font-family="Arial">HM</text></svg>
        <div class="brand-text">
          <strong class="name">{{BUSINESS_NAME}}</strong>
          <small class="tag">A whole-person approach — {{TAGLINE}}</small>
        </div>
      </div>
      <nav class="nav">
        <button class="nav-toggle" aria-label="Toggle menu">☰</button>
        <ul class="nav-list">
          <li><a href="/">Home</a></li>
          <li><a href="/services.html">Offerings</a></li>
          <li><a href="/conditions.html">Conditions</a></li>
          <li><a href="/approach.html">Our Process</a></li>
          <li><a href="/pricing.html">Investment</a></li>
          <li><a href="/about.html">Team</a></li>
          <li><a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
    </header>

    <main>
      <!-- HERO -->
      <section id="hero" class="hero">
        <div class="hero-inner glass">
          <h1>Holistic medicine that connects context, biomarkers, and habits</h1>
          <p class="lede">Work with {{PRACTITIONER_NAME}}, {{CREDENTIALS}}, to create a clear, practical plan that addresses root drivers — stress, sleep, digestion, and energy — without promising quick fixes.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/book.html">Book a consult</a>
          </div>
          <p class="contact">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </section>

      <!-- DIAGNOSTIC -->
      <section id="diagnostic" class="panel">
        <div class="panel-inner glass">
          <h2>Comprehensive intake + evidence-aware diagnostics</h2>
          <p>We begin by understanding your story and context: medical history, sleep patterns, stressors, movement, and digestion. If indicated, we discuss targeted labs as educational tools to inform your personalized plan.</p>
          <ul class="features">
            <li><strong>Intake interview</strong> — whole-person history and priorities</li>
            <li><strong>Optional labs</strong> — interpreted with practical next steps (educational)</li>
            <li><strong>Functional assessments</strong> — sleep, diet, movement, and stress mapping</li>
          </ul>
        </div>
      </section>

      <!-- PLAN -->
      <section id="plan" class="panel alt">
        <div class="panel-inner glass">
          <h2>Tailored plan: clear steps, measurable goals</h2>
          <p>Your plan centers on simple, sustainable actions supported by targeted labs and follow-up. For VIP clients, we offer an intensive VIP Day to jump-start progress with focused assessment and immediate coaching.</p>
          <ol class="plan-list">
            <li><strong>Understand</strong> — intake & data interpretation</li>
            <li><strong>Prioritize</strong> — select 1–3 high-impact changes</li>
            <li><strong>Act</strong> — micro-habits and supportive therapies</li>
            <li><strong>Follow</strong> — check-ins, iterate, and refine</li>
          </ol>
        </div>
      </section>

      <!-- MICRO HABITS -->
      <section id="micro_habits" class="panel">
        <div class="panel-inner glass">
          <h2>Micro-habits that move the needle</h2>
          <p>Small changes compound. Below are practical habits you can start this week to support sleep, digestion, and energy.</p>
          <div class="habits-grid">
            <div class="habit">
              <h3>Sleep reset</h3>
              <p>Dim lights 60–90 minutes before bed, and keep a regular wake time. Track sleep window for two weeks.</p>
            </div>
            <div class="habit">
              <h3>Digestive rhythm</h3>
              <p>Prioritize protein at breakfast, chew slowly, and record reactions to identify triggers with awareness — not restriction.</p>
            </div>
            <div class="habit">
              <h3>Stress micro-breaks</h3>
              <p>Three 90-second diaphragmatic breathing breaks per day to reduce acute stress reactivity.</p>
            </div>
            <div class="habit">
              <h3>Energy pacing</h3>
              <p>Alternate focused work with 10-minute walks to stabilize energy without overstimulation.</p>
            </div>
          </div>
        </div>
      </section>

      <!-- PRICING TEASER -->
      <section id="pricing" class="panel pricing">
        <div class="panel-inner glass">
          <h2>Investment options — including VIP Day</h2>
          <p>We offer flexible packages: single visits, short-term plans, and an immersive VIP Day for concentrated assessment and planning. Pricing varies; see full details on the Investment page.</p>
          <div class="pricing-cta">
            <a class="btn" href="/pricing.html">See full pricing</a>
            <a class="btn primary" href="/book.html">Reserve a VIP Day</a>
          </div>
        </div>
      </section>

      <!-- CTA FOOTER -->
      <section id="cta" class="cta-panel">
        <div class="panel-inner glass">
          <h2>Ready for a practical, whole-person plan?</h2>
          <p>Schedule a consult or inquire about a VIP Day. We focus on education, realistic goals, and measurable progress — no cure promises, just clear steps.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/contact.html">Contact us</a>
          </div>
        </div>
      </section>
    </main>

    <footer class="site-foot">
      <div>
        <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</p>
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </footer>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
